    private static readonly Lazy<ImageSource?> PotatoeBackgroundLazy =
        new(CreatePotatoeBackground);

    public static ImageSource? PotatoeBackground =>
        PotatoeBackgroundLazy.Value;

    private static ImageSource? CreatePotatoeBackground()
    {
        try
        {
            byte[] bytes = Convert.FromBase64String(
                PotatoeBackgroundBase64
            );

            using MemoryStream stream = new(bytes, writable: false);

            BitmapImage image = new();
            image.BeginInit();
            image.CacheOption = BitmapCacheOption.OnLoad;
            image.CreateOptions = BitmapCreateOptions.PreservePixelFormat;
            image.StreamSource = stream;
            image.EndInit();
            image.Freeze();
            return image;
        }
        catch
        {
            // A missing background should never stop the combat tracker.
            return null;
        }
    }

